"use client";

import { type ComponentPropsWithoutRef, forwardRef } from "react";
import { InspectorField, InspectorFieldLabel, InspectorFieldMessage, InspectorFieldSelect, InspectorFieldText } from "@/components/ui/inspector-field";
import { NumberField, NumberFieldError, NumberFieldLabel, NumberFieldSlider, NumberFieldSliderFill, NumberFieldSliderThumb, NumberFieldValue } from "@/components/ui/number-field";
import { parseCurveText, sameCurve } from "./easing-curve-editor-math";
import { useEasingCurveEditor } from "./easing-curve-editor-state";
import { cn } from "@/lib/utils";

const customValue = "custom";
type PartProps = Omit<ComponentPropsWithoutRef<"div">, "children">;

/** A menu of named curves. It shows Custom when the curve matches none of them. */
export const EasingCurvePresets = forwardRef<HTMLDivElement, PartProps>(function EasingCurvePresets({ className, ...props }, ref) {
  const { value, presets, container, mixed, disabled, readOnly, messages, commitCurve } = useEasingCurveEditor();
  const current = presets.find((preset) => sameCurve(preset.curve, value));
  const options = presets.map((preset) => ({ value: preset.value, label: preset.label, disabled: false }));
  if (!current && !mixed) options.push({ value: customValue, label: messages.custom, disabled: true });
  return (
    <InspectorField ref={ref} data-slot="easing-curve-presets" label={messages.preset} labelPosition="inside" mixed={mixed} disabled={disabled} readOnly={readOnly} className={cn("min-w-0 [--uicoolkit-field-bg:var(--muted)] [--uicoolkit-field-border:transparent] [--uicoolkit-field-shadow:none]", className)} {...props}>
      <InspectorFieldLabel />
      <InspectorFieldSelect
        value={current?.value ?? customValue}
        options={options}
        container={container}
        positionMethod={container ? "fixed" : undefined}
        onCommit={(next) => {
          const preset = presets.find((item) => item.value === next);
          if (preset) commitCurve(preset.curve, "preset");
        }}
      />
    </InspectorField>
  );
});

/** All four numbers in one field. It also accepts cubic-bezier() and CSS keywords. */
export const EasingCurveEaseField = forwardRef<HTMLDivElement, PartProps>(function EasingCurveEaseField({ className, ...props }, ref) {
  const { value, range, mixed, disabled, readOnly, messages, commitCurve } = useEasingCurveEditor();
  return (
    <InspectorField ref={ref} data-slot="easing-curve-ease" label={messages.ease} labelPosition="inside" mixed={mixed} disabled={disabled} readOnly={readOnly} className={cn("min-w-0 [--uicoolkit-field-bg:var(--muted)] [--uicoolkit-field-border:transparent] [--uicoolkit-field-shadow:none]", className)} {...props}>
      <InspectorFieldLabel />
      <InspectorFieldText
        value={value.join(", ")}
        validate={(text) => (parseCurveText(text, range) ? null : messages.invalidCurve(range[0], range[1]))}
        onCommit={(text) => {
          const curve = parseCurveText(text, range);
          if (curve) commitCurve(curve, "field");
        }}
      />
      <InspectorFieldMessage />
    </InspectorField>
  );
});

/** A slider for how long the transition runs. Your app owns the value. */
export const EasingCurveDurationField = forwardRef<HTMLDivElement, PartProps>(function EasingCurveDurationField({ className, ...props }, ref) {
  const { duration, durationRange, onDurationChange, onDurationCommit, mixed, disabled, readOnly, messages } = useEasingCurveEditor();
  if (duration === undefined) return null;
  return (
    <NumberField
      ref={ref}
      data-slot="easing-curve-duration"
      className={cn("min-w-0", className)}
      label={messages.duration}
      value={mixed ? null : duration}
      placeholder={messages.mixed}
      min={durationRange.min}
      max={durationRange.max}
      step={durationRange.step}
      unit={durationRange.unit}
      disabled={disabled}
      readOnly={readOnly}
      onValueChange={onDurationChange}
      onValueCommit={(next) => onDurationCommit?.(next)}
      {...props}
    >
      <NumberFieldSlider className="h-[var(--uicoolkit-field-height,2.5rem)]">
        <NumberFieldSliderFill />
        <NumberFieldSliderThumb />
        <NumberFieldLabel />
        <NumberFieldValue />
      </NumberFieldSlider>
      <NumberFieldError />
    </NumberField>
  );
});

/** The Ease field, and the Duration field when your app passes a duration. */
export const EasingCurveFields = forwardRef<HTMLDivElement, ComponentPropsWithoutRef<"div">>(function EasingCurveFields({ className, children, ...props }, ref) {
  return (
    <div ref={ref} data-slot="easing-curve-fields" className={cn("grid gap-2", className)} {...props}>
      {children ?? (
        <>
          <EasingCurveEaseField />
          <EasingCurveDurationField />
        </>
      )}
    </div>
  );
});

"use client";

import { type PointerEvent, useCallback, useEffect, useRef, useState } from "react";
import { type EasingCurveHandle, type EasingCurveRange, type EasingCurveValue, handlePoint, moveHandle, ratioToX, ratioToY, sameCurve, xToRatio, yToRatio } from "./easing-curve-editor-math";
import { type EasingCurveDetail, useIsomorphicLayoutEffect } from "./easing-curve-editor-state";

type Options = {
  value: EasingCurveValue;
  range: EasingCurveRange;
  step: number;
  enabled: boolean;
  trackRef: { current: HTMLDivElement | null };
  handleRefs: { current: (HTMLDivElement | null)[] };
  setLive: (value: EasingCurveValue | null) => void;
  onValueChange?: (value: EasingCurveValue, detail: EasingCurveDetail) => void;
  onValueCommit: (value: EasingCurveValue, detail: EasingCurveDetail) => void;
};

type Drag = {
  id: number;
  handle: EasingCurveHandle;
  start: EasingCurveValue;
  last: EasingCurveValue;
  element: HTMLElement;
  /** How far the press landed from the handle's center, so grabbing it never makes it jump. */
  offsetX: number;
  offsetY: number;
};

const unit = (value: number) => Math.min(Math.max(value, 0), 1);

/** Press a handle and drag to move it. Escape cancels. Presses elsewhere on the surface do nothing. */
export function useEasingCurveDrag(options: Options) {
  const [activeHandle, setActiveHandle] = useState<EasingCurveHandle | null>(null);
  const [pointerFocus, setPointerFocus] = useState(false);
  const drag = useRef<Drag | null>(null);
  const latest = useRef(options);
  useIsomorphicLayoutEffect(() => {
    latest.current = options;
  });

  const ratioAt = useCallback((clientX: number, clientY: number) => {
    const box = latest.current.trackRef.current?.getBoundingClientRect();
    if (!box || box.width === 0 || box.height === 0) return { x: 0, y: 0 };
    return { x: unit((clientX - box.left) / box.width), y: unit((clientY - box.top) / box.height) };
  }, []);

  const update = useCallback(
    (active: Drag, clientX: number, clientY: number) => {
      const { range, step, setLive, onValueChange } = latest.current;
      const ratio = ratioAt(clientX, clientY);
      const next = moveHandle(active.start, active.handle, { x: ratioToX(unit(ratio.x - active.offsetX)), y: ratioToY(unit(ratio.y - active.offsetY), range) }, range, step);
      if (sameCurve(next, active.last)) return;
      active.last = next;
      setLive(next);
      onValueChange?.(next, { handle: active.handle, source: "pointer" });
    },
    [ratioAt],
  );

  const finish = useCallback((cancel: boolean) => {
    const active = drag.current;
    if (!active) return;
    drag.current = null;
    const { setLive, onValueChange, onValueCommit } = latest.current;
    const detail: EasingCurveDetail = { handle: active.handle, source: "pointer" };
    const changed = !sameCurve(active.start, active.last);
    if (changed && cancel) onValueChange?.(active.start, detail);
    if (changed && !cancel) onValueCommit(active.last, detail);
    setLive(null);
    setActiveHandle(null);
    if (active.element.hasPointerCapture?.(active.id)) active.element.releasePointerCapture(active.id);
  }, []);

  useEffect(() => {
    if (activeHandle === null) return;
    const onKey = (event: KeyboardEvent) => {
      if (event.key !== "Escape") return;
      event.preventDefault();
      event.stopPropagation();
      finish(true);
    };
    const onBlur = () => finish(true);
    const onPointerEnd = (event: globalThis.PointerEvent) => {
      if (drag.current?.id === event.pointerId) finish(event.type === "pointercancel");
    };
    window.addEventListener("keydown", onKey, true);
    window.addEventListener("blur", onBlur);
    window.addEventListener("pointerup", onPointerEnd);
    window.addEventListener("pointercancel", onPointerEnd);
    return () => {
      window.removeEventListener("keydown", onKey, true);
      window.removeEventListener("blur", onBlur);
      window.removeEventListener("pointerup", onPointerEnd);
      window.removeEventListener("pointercancel", onPointerEnd);
    };
  }, [activeHandle, finish]);

  useEffect(() => () => finish(true), [finish]);

  const surfaceHandlers = {
    onPointerDown: (event: PointerEvent<HTMLDivElement>) => {
      if (event.defaultPrevented || event.button !== 0 || !options.enabled || drag.current) return;
      const target = event.target as Node;
      if (!options.handleRefs.current.some((element) => element?.contains(target))) return;
      event.preventDefault();
      const ratio = ratioAt(event.clientX, event.clientY);
      const offset = (handle: EasingCurveHandle) => {
        const point = handlePoint(options.value, handle);
        return { x: ratio.x - xToRatio(point.x), y: ratio.y - yToRatio(point.y, options.range) };
      };
      // Grab areas can overlap when handles sit close together, so the nearer handle wins.
      const distance = (handle: EasingCurveHandle) => Math.hypot(offset(handle).x, offset(handle).y);
      const handle: EasingCurveHandle = distance(1) < distance(0) ? 1 : 0;
      const grab = offset(handle);
      const active: Drag = { id: event.pointerId, handle, start: options.value, last: options.value, element: event.currentTarget, offsetX: grab.x, offsetY: grab.y };
      drag.current = active;
      try {
        event.currentTarget.setPointerCapture?.(event.pointerId);
      } catch {
        // The pointer may already have ended; the window listener still finishes the drag.
      }
      setPointerFocus(true);
      options.handleRefs.current[handle]?.focus({ preventScroll: true });
      setActiveHandle(handle);
    },
    onPointerMove: (event: PointerEvent<HTMLDivElement>) => {
      const active = drag.current;
      if (active?.id === event.pointerId) update(active, event.clientX, event.clientY);
    },
    onPointerUp: (event: PointerEvent<HTMLDivElement>) => {
      if (drag.current?.id === event.pointerId) finish(false);
    },
    onPointerCancel: (event: PointerEvent<HTMLDivElement>) => {
      if (drag.current?.id === event.pointerId) finish(true);
    },
    onLostPointerCapture: (event: PointerEvent<HTMLDivElement>) => {
      if (drag.current?.id === event.pointerId) finish(true);
    },
  };

  return { activeHandle, pointerFocus, setPointerFocus, surfaceHandlers, isDragging: () => drag.current !== null };
}

/** A cubic Bézier easing: [x1, y1, x2, y2]. */
export type EasingCurveValue = readonly [number, number, number, number];
export type EasingCurveHandle = 0 | 1;
export type EasingCurvePoint = { x: number; y: number };
/** The lowest and highest progress the surface shows. */
export type EasingCurveRange = readonly [number, number];
export type EasingCurvePreset = { value: string; label: string; curve: EasingCurveValue };

/** One grid cell of six on each side, so the 0 to 1 area lands on grid lines and overshoot has room. */
export const defaultRange: EasingCurveRange = [-0.25, 1.25];
const plotInset = 1 / 6;

export const defaultPresets: EasingCurvePreset[] = [
  { value: "linear", label: "Linear", curve: [0, 0, 1, 1] },
  { value: "ease", label: "Ease", curve: [0.25, 0.1, 0.25, 1] },
  { value: "ease-in", label: "Ease in", curve: [0.42, 0, 1, 1] },
  { value: "ease-out", label: "Ease out", curve: [0, 0, 0.58, 1] },
  { value: "ease-in-out", label: "Ease in-out", curve: [0.42, 0, 0.58, 1] },
];

const clamp = (value: number, min: number, max: number) => Math.min(Math.max(value, min), max);
const decimals = (value: number) => (String(value).split(".")[1] ?? "").length;

export const xToRatio = (x: number) => plotInset + x * (1 - plotInset * 2);
export const ratioToX = (ratio: number) => (ratio - plotInset) / (1 - plotInset * 2);
export const yToRatio = (y: number, [min, max]: EasingCurveRange) => (max - y) / (max - min);
export const ratioToY = (ratio: number, [min, max]: EasingCurveRange) => max - ratio * (max - min);

export const handlePoint = (value: EasingCurveValue, handle: EasingCurveHandle): EasingCurvePoint => ({ x: value[handle * 2], y: value[handle * 2 + 1] });
export const sameCurve = (a: EasingCurveValue, b: EasingCurveValue) => a.every((coordinate, index) => coordinate === b[index]);

function snap(value: number, step: number) {
  return step > 0 ? Number((Math.round(value / step) * step).toFixed(decimals(step))) : value;
}

/** Moves one handle, keeping X from 0 to 1 and Y inside the range. */
export function moveHandle(value: EasingCurveValue, handle: EasingCurveHandle, point: EasingCurvePoint, range: EasingCurveRange = defaultRange, step = 0.01): EasingCurveValue {
  const x = clamp(snap(point.x, step), 0, 1);
  const y = clamp(snap(point.y, step), range[0], range[1]);
  return handle === 0 ? [x, y, value[2], value[3]] : [value[0], value[1], x, y];
}

const bezier = (a: number, b: number, t: number) => 3 * a * (1 - t) ** 2 * t + 3 * b * (1 - t) * t ** 2 + t ** 3;

/** The progress at a moment from 0 to 1. */
export function cubicBezierAt([x1, y1, x2, y2]: EasingCurveValue, time: number) {
  if (time <= 0) return 0;
  if (time >= 1) return 1;
  let low = 0;
  let high = 1;
  for (let index = 0; index < 32; index += 1) {
    const middle = (low + high) / 2;
    if (bezier(x1, x2, middle) < time) low = middle;
    else high = middle;
  }
  return bezier(y1, y2, (low + high) / 2);
}

export const formatCubicBezier = (value: EasingCurveValue) => `cubic-bezier(${value.join(", ")})`;

/** Reads cubic-bezier() or a CSS keyword. Returns null for anything else, including X outside 0 to 1. */
export function parseCubicBezier(text: string): EasingCurveValue | null {
  const source = text.trim().toLowerCase();
  const keyword = defaultPresets.find((preset) => preset.value === source);
  if (keyword) return keyword.curve;
  const match = /^cubic-bezier\(([^)]*)\)$/.exec(source);
  const parts = match?.[1].split(",").map((part) => (part.trim() === "" ? Number.NaN : Number(part)));
  if (parts?.length !== 4 || parts.some((part) => !Number.isFinite(part))) return null;
  const [x1, y1, x2, y2] = parts;
  return x1 < 0 || x1 > 1 || x2 < 0 || x2 > 1 ? null : [x1, y1, x2, y2];
}

/** Reads typed text: four numbers, cubic-bezier() or a CSS keyword, with Y inside the range. */
export function parseCurveText(text: string, range: EasingCurveRange = defaultRange): EasingCurveValue | null {
  const source = text.trim();
  const curve = parseCubicBezier(source) ?? parseCubicBezier(`cubic-bezier(${source})`);
  if (!curve) return null;
  return [curve[1], curve[3]].every((y) => y >= range[0] && y <= range[1]) ? curve : null;
}

const toViewBox = (ratio: number) => Number((ratio * 100).toFixed(3));

/** An SVG path for the curve, in a 100 by 100 view box. */
export function curvePath(value: EasingCurveValue, range: EasingCurveRange) {
  const point = (x: number, y: number) => `${toViewBox(xToRatio(x))} ${toViewBox(yToRatio(y, range))}`;
  return `M ${point(0, 0)} C ${point(value[0], value[1])} ${point(value[2], value[3])} ${point(1, 1)}`;
}

/** An SVG path that samples any easing function, such as a spring. */
export function easingPath(easing: (time: number) => number, range: EasingCurveRange, samples = 64) {
  const count = Math.max(samples, 2);
  return Array.from({ length: count + 1 }, (_, index) => {
    const time = index / count;
    return `${index === 0 ? "M" : "L"} ${toViewBox(xToRatio(time))} ${toViewBox(yToRatio(easing(time), range))}`;
  }).join(" ");
}

"use client";

import { type ComponentPropsWithoutRef, forwardRef } from "react";
import { type EasingCurveHandle, type EasingCurveRange, curvePath, defaultRange, easingPath, handlePoint, xToRatio, yToRatio } from "./easing-curve-editor-math";
import { useEasingCurveEditor } from "./easing-curve-editor-state";
import { cn } from "@/lib/utils";

const surfaceClass = "relative aspect-square w-full rounded-md border border-input bg-muted/40";
const percent = (ratio: number) => `${ratio * 100}%`;

/** The editor's visible name. Place it above the surface. Pass children to replace the text. */
export const EasingCurveLabel = forwardRef<HTMLSpanElement, ComponentPropsWithoutRef<"span">>(function EasingCurveLabel({ className, children, ...props }, ref) {
  const { label } = useEasingCurveEditor();
  return (
    <span ref={ref} aria-hidden data-slot="easing-curve-label" className={cn("truncate text-sm leading-5 text-muted-foreground", className)} {...props}>
      {children ?? label}
    </span>
  );
});

type GridProps = ComponentPropsWithoutRef<"div"> & {
  /** How many equal cells run across each direction. */
  cells?: number;
};

/** Equal square cells. Lines sit only between cells, so none run along the edges. */
export const EasingCurveGrid = forwardRef<HTMLDivElement, GridProps>(function EasingCurveGrid({ cells = 6, className, ...props }, ref) {
  const stops = Array.from({ length: Math.max(cells - 1, 0) }, (_, index) => (index + 1) / cells);
  return (
    <div ref={ref} aria-hidden data-slot="easing-curve-grid" className={cn("pointer-events-none absolute inset-0 text-foreground/15", className)} {...props}>
      {stops.map((stop) => (
        <span key={`x${stop}`} data-slot="easing-curve-grid-line" className="absolute inset-y-0 w-px -translate-x-1/2 bg-current" style={{ left: percent(stop) }} />
      ))}
      {stops.map((stop) => (
        <span key={`y${stop}`} data-slot="easing-curve-grid-line" className="absolute inset-x-0 h-px -translate-y-1/2 bg-current" style={{ top: percent(stop) }} />
      ))}
    </div>
  );
});

const svgClass = "pointer-events-none absolute inset-0 size-full overflow-visible";
const stroke = { fill: "none", vectorEffect: "non-scaling-stroke" } as const;

/** The curve, with thin lines from its start and end to the handles. */
export const EasingCurveLine = forwardRef<SVGSVGElement, ComponentPropsWithoutRef<"svg">>(function EasingCurveLine({ className, ...props }, ref) {
  const { value, range, mixed } = useEasingCurveEditor();
  const position = (x: number, y: number) => ({ x: xToRatio(x) * 100, y: yToRatio(y, range) * 100 });
  const start = position(0, 0);
  const end = position(1, 1);
  const first = position(value[0], value[1]);
  const second = position(value[2], value[3]);
  return (
    <svg ref={ref} aria-hidden data-slot="easing-curve-line" viewBox="0 0 100 100" preserveAspectRatio="none" className={cn(svgClass, mixed && "opacity-40", className)} {...props}>
      <line {...stroke} data-slot="easing-curve-arm" x1={start.x} y1={start.y} x2={first.x} y2={first.y} className="stroke-muted-foreground/70" strokeWidth={1} />
      <line {...stroke} data-slot="easing-curve-arm" x1={end.x} y1={end.y} x2={second.x} y2={second.y} className="stroke-muted-foreground/70" strokeWidth={1} />
      <path {...stroke} data-slot="easing-curve-path" d={curvePath(value, range)} className="stroke-foreground" strokeWidth={1.5} strokeLinecap="round" />
    </svg>
  );
});

type HandleProps = Omit<ComponentPropsWithoutRef<"div">, "children"> & {
  handle: EasingCurveHandle;
};

/** One solid handle. It holds keyboard focus for its point and grows with a soft halo while dragged. */
export const EasingCurveHandlePoint = forwardRef<HTMLDivElement, HandleProps>(function EasingCurveHandlePoint({ handle, className, style, onKeyDown, onBlur, ...props }, ref) {
  const { value, range, disabled, readOnly, motion, activeHandle, pointerFocus, messages, handleRefs, onHandleKeyDown, onHandleBlur } = useEasingCurveEditor();
  const point = handlePoint(value, handle);
  return (
    <div
      ref={(element) => {
        handleRefs.current[handle] = element;
        if (typeof ref === "function") ref(element);
        else if (ref) ref.current = element;
      }}
      role="slider"
      tabIndex={disabled ? undefined : 0}
      aria-label={messages.handle(handle + 1)}
      aria-valuemin={0}
      aria-valuemax={1}
      aria-valuenow={point.x}
      aria-valuetext={messages.point(point.x, point.y)}
      aria-disabled={disabled || undefined}
      aria-readonly={readOnly || undefined}
      data-slot="easing-curve-handle"
      data-active={activeHandle === handle ? "" : undefined}
      data-pointer-focus={pointerFocus ? "" : undefined}
      className={cn(
        "absolute size-3 -translate-x-1/2 -translate-y-1/2 rounded-full bg-primary shadow-sm outline-none",
        // The grab area is larger than the dot, and larger again for touch.
        disabled || readOnly ? "pointer-events-none" : "cursor-grab touch-none after:absolute after:-inset-1.5 after:rounded-full pointer-coarse:after:-inset-3.5",
        "data-active:scale-125 data-active:ring-4 data-active:ring-primary/25 [&:focus-visible:not([data-pointer-focus])]:ring-2 [&:focus-visible:not([data-pointer-focus])]:ring-primary/40",
        motion && "transition-[scale,box-shadow] duration-100 ease-out motion-reduce:transition-none",
        className,
      )}
      style={{ ...style, left: percent(xToRatio(point.x)), top: percent(yToRatio(point.y, range)) }}
      onKeyDown={(event) => {
        onKeyDown?.(event);
        if (!event.defaultPrevented) onHandleKeyDown(event, handle);
      }}
      onBlur={(event) => {
        onBlur?.(event);
        onHandleBlur();
      }}
      {...props}
    />
  );
});

/** The square that holds the curve. Drag its handles to edit. It highlights while dragging and on keyboard focus. */
export const EasingCurveSurface = forwardRef<HTMLDivElement, ComponentPropsWithoutRef<"div">>(function EasingCurveSurface(
  { className, children, onPointerDown, onPointerMove, onPointerUp, onPointerCancel, onLostPointerCapture, ...props },
  ref,
) {
  const { disabled, activeHandle, trackRef, surfaceHandlers } = useEasingCurveEditor();
  return (
    <div
      ref={ref}
      data-slot="easing-curve-surface"
      data-dragging={activeHandle !== null ? "" : undefined}
      className={cn(
        surfaceClass,
        "select-none data-dragging:cursor-grabbing data-dragging:border-primary data-dragging:bg-primary/5 has-[[data-slot=easing-curve-handle]:focus-visible:not([data-pointer-focus])]:border-primary",
        disabled && "cursor-not-allowed opacity-50",
        className,
      )}
      onPointerDown={(event) => {
        onPointerDown?.(event);
        surfaceHandlers.onPointerDown(event);
      }}
      onPointerMove={(event) => {
        onPointerMove?.(event);
        surfaceHandlers.onPointerMove(event);
      }}
      onPointerUp={(event) => {
        onPointerUp?.(event);
        surfaceHandlers.onPointerUp(event);
      }}
      onPointerCancel={(event) => {
        onPointerCancel?.(event);
        surfaceHandlers.onPointerCancel(event);
      }}
      onLostPointerCapture={(event) => {
        onLostPointerCapture?.(event);
        surfaceHandlers.onLostPointerCapture(event);
      }}
      {...props}
    >
      <div ref={trackRef} data-slot="easing-curve-track" className="absolute inset-0">
        {children ?? (
          <>
            <EasingCurveGrid />
            <EasingCurveLine />
            <EasingCurveHandlePoint handle={0} />
            <EasingCurveHandlePoint handle={1} />
          </>
        )}
      </div>
    </div>
  );
});

type GraphProps = Omit<ComponentPropsWithoutRef<"div">, "children"> & {
  /** Maps time from 0 to 1 to progress, such as a spring your app calculates. */
  easing: (time: number) => number;
  /** Accessible description of the curve. */
  label: string;
  /** The lowest and highest progress shown. Widen it for springs that overshoot further. */
  range?: EasingCurveRange;
  samples?: number;
};

/** A read-only graph of any easing function. It needs no editor around it. */
export const EasingCurveGraph = forwardRef<HTMLDivElement, GraphProps>(function EasingCurveGraph({ easing, label, range = defaultRange, samples, className, ...props }, ref) {
  return (
    <div ref={ref} role="img" aria-label={label} data-slot="easing-curve-graph" className={cn(surfaceClass, "w-60 max-w-full", className)} {...props}>
      <EasingCurveGrid />
      <svg aria-hidden viewBox="0 0 100 100" preserveAspectRatio="none" className={svgClass}>
